#!/usr/bin/env python3
"""Run C1 Unit01 recalibration with narrow length and assessment fixes."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit01.py')
text=SOURCE.read_text(encoding='utf-8')
old_p02="في النهاية نشر الفريق أرقامًا متعددة بحسب طريقة الجمع بدل رقم واحد يخفي هذا الاعتماد، وشرح لماذا لا تكون زيادة العدد بديلًا عن فهم الطريق الذي دخلت منه البيانات.''',"
new_p02="في النهاية نشر الفريق أرقامًا متعددة بحسب طريقة الجمع بدل رقم واحد يخفي هذا الاعتماد، وشرح لماذا لا تكون زيادة العدد بديلًا عن فهم الطريق الذي دخلت منه البيانات. وأضافوا مقارنة بين خصائص من استجابوا مبكرًا ومن استجابوا بعد تذكير ثان، لأن الفروق بين المجموعتين قد تقدم إشارة جزئية إلى نمط عدم الاستجابة. لم تعامل هذه المقارنة من لم يجيبوا كأنهم معروفون، لكنها وفرت اختبارًا إضافيًا لحساسية الوصف وبيّنت أي النتائج تستحق لغة أكثر تحفظًا.''',"
old_p06="عندما يصبح موضع الخلاف واضحًا، يمكن اختيار دراسة لاحقة تستهدفه بدل تكرار نقاش عام لا يتغير.''',"
new_p06="عندما يصبح موضع الخلاف واضحًا، يمكن اختيار دراسة لاحقة تستهدفه بدل تكرار نقاش عام لا يتغير. ولتختبر اتساق الخريطة، أعطتها سلمى لزميل لم يشارك في المشروع وطلبت منه إعادة بناء سبب كل استنتاج من الجدول وحده. عندما عجز عن تفسير انتقالين، عادت إلى النص وأضافت الافتراضات الناقصة بدل الاكتفاء بعبارة أقوى. ثم طلبت منه أن يقترح نتيجة افتراضية تعاكس كل ادعاء رئيسي، حتى تتأكد من أن درجة الثقة قابلة للانخفاض وليست محمية من أي دليل محتمل. بهذه المراجعة أصبحت الخريطة أداة تواصل واختبار معًا: لا تعرض ما يعتقده الفريق فقط، بل تسمح لقارئ مستقل بمعرفة أين يمكن فحص الاعتقاد وكيف يمكن أن يتغير.''',"
old_q8="'q8':('grammar_function','ما وظيفة «أما» في التفريق بين عبارات يكفي تضييقها وعبارات تحتاج إلى تصميم جديد؟',None,'تقابل مشكلة في صياغة نطاق الادعاء بمشكلة أدلة فعلية، فتحدد متى يكفي تعديل اللغة ومتى يلزم جمع معلومات جديدة.'),},"
new_q8="'q8':('grammar_function','ما وظيفة «أما» في التفريق بين عبارات يكفي تضييقها وعبارات تحتاج إلى تصميم جديد؟',None,'تقابل مشكلة في صياغة نطاق الادعاء بمشكلة أدلة فعلية، فتحدد متى يكفي تعديل اللغة ومتى يلزم جمع معلومات جديدة.'),\n'q10':('grammar_function','ما وظيفة «بدل» في قول النص «بدل تكرار نقاش عام لا يتغير»؟',None,'تستبدل نقاشًا واسعًا متكررًا بدراسة موجهة إلى موضع الخلاف المحدد، فتوضح وظيفة الانتقال من الجدل العام إلى اختبار قابل للحسم النسبي.'),},"
assert text.count(old_p02)==1,'expected exactly one C1 Unit01 P02 insertion point'
assert text.count(old_p06)==1,'expected exactly one C1 Unit01 P06 insertion point'
assert text.count(old_q8)==1,'expected exactly one C1 Unit01 P06 assessment insertion point'
assert text.count('assert len(changes)==14,len(changes)')==1,'expected C1 Unit01 change-count guard'
patched=(text.replace(old_p02,new_p02)
             .replace(old_p06,new_p06)
             .replace(old_q8,new_q8)
             .replace('assert len(changes)==14,len(changes)','assert len(changes)==15,len(changes)'))
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
